def build_table(pairs, size):
    table = [[] for _ in range(size)]
    for key, value in pairs:
        chain = table[sum(ord(ch) for ch in key) % size]
        for pair in chain:
            if pair[0] == key:
                pair[1] = value
                break
        else:
            chain.append([key, value])
    return table

